export default function AppShell(){
 const path=usePathname(); const router=useRouter();
 const [ready,setReady]=useState(false); const [authed,setAuthed]=useState(false); const [menu,setMenu]=useState(false); const [language,setLanguage]=useState<Language>("en");
 const [farmers,setFarmers]=useState<Farmer[]>(initialFarmers); const [collections,setCollections]=useState<Collection[]>(initialCollections); const [search,setSearch]=useState("");
 const [showAddFarmer,setShowAddFarmer]=useState(false); const [showGive,setShowGive]=useState(false); const [showUser,setShowUser]=useState(false); const [showProfile,setShowProfile]=useState(false); const [currentUser,setCurrentUser]=useState("admin"); const [users,setUsers]=useState<User[]>([{username:"admin",password:"shivam123"}]);
 const t=tx[language];
 const page=useMemo(()=>path==="/"?"dashboard":path.split("/")[1]||"dashboard",[path]);
 useEffect(()=>{if(typeof window==="undefined")return; const u=localStorage.getItem("shivam-auth"); const lang=(localStorage.getItem("shivam-lang")||"en") as Language; setLanguage(lang); const fs=localStorage.getItem("shivam-farmers"); const cs=localStorage.getItem("shivam-collections"); const us=localStorage.getItem("shivam-users"); if(fs) setFarmers(JSON.parse(fs)); if(cs) setCollections(JSON.parse(cs)); if(us) setUsers(JSON.parse(us)); if(u){const s=JSON.parse(u); if(Date.now()<s.expires){setAuthed(true);setCurrentUser(s.username||"admin");}else localStorage.removeItem("shivam-auth");} setReady(true);},[]);
 useEffect(()=>{if(!ready)return; localStorage.setItem("shivam-farmers",JSON.stringify(farmers)); localStorage.setItem("shivam-collections",JSON.stringify(collections)); localStorage.setItem("shivam-users",JSON.stringify(users)); localStorage.setItem("shivam-lang",language);},[ready,farmers,collections,users,language]);
 useEffect(()=>{if(!authed)return; const i=setInterval(()=>{const s=localStorage.getItem("shivam-auth"); if(!s)return; if(Date.now()>=JSON.parse(s).expires){localStorage.removeItem("shivam-auth"); setAuthed(false);}},15000); return()=>clearInterval(i);},[authed]);
 useEffect(()=>{setMenu(false);setShowAddFarmer(false);setShowGive(false);setShowUser(false);setShowProfile(false);},[path]);
 if(!ready) return <div className="min-h-screen bg-[#f5f7f4]"/>;
 if(!authed) return <Login language={language} setLanguage={setLanguage} users={users} onLogin={(u)=>{localStorage.setItem("shivam-auth",JSON.stringify({username:u,expires:Date.now()+60*60*1000}));setCurrentUser(u);setAuthed(true)}}/>;
 const farmerDetailId=path.match(/^\/farmers\/(\d+)$/)?.[1];
 const title=page==="dashboard"?t.dashboard:page==="farmers"?t.farmers:page==="collections"?t.pickUpTitle:page==="reports"?t.reports:page==="settings"?t.settings:page==="give-crates"?t.giveCrates:page==="collect"?t.recordPickup:page==="pending"?t.pendingTab:page==="wholesalers"?t.wholesalers:page==="crate-types"?t.crateTypes:page==="whatsapp"?t.whatsappPage:"Shivam Collection";
 const logout=()=>{localStorage.removeItem("shivam-auth");setAuthed(false)};
 const addFarmer=(f:Omit<Farmer,"id"|"given"|"collected"|"pending">)=>{setFarmers(v=>[...v,{...f,id:Date.now(),given:0,collected:0,pending:0}]);setShowAddFarmer(false)};
 const giveCrates=(farmerId:number,qty:number)=>{setFarmers(v=>v.map(f=>f.id===farmerId?{...f,given:f.given+qty,pending:f.pending+qty}:f));setShowGive(false)};
 const createCollection=(data:Omit<Collection,"id">)=>{setCollections(v=>[{...data,id:Date.now()},...v]);setFarmers(v=>v.map(f=>f.id===data.farmerId?{...f,collected:f.collected+data.collected,pending:Math.max(0,f.pending-data.collected)}:f));};
 return <div className="min-h-screen bg-[#f5f7f4]">
  <header className="sticky top-0 z-40 border-b border-gray-200 bg-white/95 backdrop-blur"><div className="mx-auto flex h-16 max-w-7xl items-center justify-between px-4 md:px-7"><div className="flex items-center gap-3"><button onClick={()=>setMenu(true)} className="rounded-xl p-2 hover:bg-gray-100 md:hidden"><Menu size={21}/></button><Link href="/" className="flex items-center gap-2.5"><span className="flex h-9 w-9 items-center justify-center rounded-xl bg-leaf-700 text-white"><Boxes size={20}/></span><span className="hidden sm:block"><b className="block text-sm">Shivam Collection</b><span className="text-[11px] text-gray-500">Farmer operations</span></span></Link></div><div className="flex items-center gap-2"><div className="hidden items-center gap-1 rounded-xl border border-gray-200 p-1 md:flex"><button onClick={()=>setLanguage("en")} className={`rounded-lg px-2.5 py-1.5 text-xs font-bold ${language==="en"?"bg-leaf-50 text-leaf-700":"text-gray-500"}`}>English</button><button onClick={()=>setLanguage("mr")} className={`rounded-lg px-2.5 py-1.5 text-xs font-bold ${language==="mr"?"bg-leaf-50 text-leaf-700":"text-gray-500"}`}>मराठी</button></div><button className="hidden rounded-xl border border-gray-200 px-3 py-2 text-xs font-semibold md:block">{new Date().toLocaleDateString(language==="mr"?"mr-IN":"en-IN",{day:"2-digit",month:"short",year:"numeric"})}</button><div className="flex items-center gap-1 rounded-xl border border-gray-200 p-1 md:hidden"><button onClick={()=>setLanguage("en")} className={`rounded-lg px-2 py-1 text-[10px] font-bold ${language==="en"?"bg-leaf-50 text-leaf-700":"text-gray-500"}`}>EN</button><button onClick={()=>setLanguage("mr")} className={`rounded-lg px-2 py-1 text-[10px] font-bold ${language==="mr"?"bg-leaf-50 text-leaf-700":"text-gray-500"}`}>मर</button></div><button className="rounded-xl p-2 hover:bg-gray-100"><Bell size={19}/></button><div className="relative"><button onClick={()=>setShowProfile(v=>!v)} title="Profile" className="flex h-9 w-9 items-center justify-center rounded-full bg-leaf-100 text-xs font-bold text-leaf-700">{currentUser.slice(0,1).toUpperCase()}</button>{showProfile&&<div className="absolute right-0 top-11 z-50 w-52 rounded-2xl border border-gray-200 bg-white p-2 shadow-xl"><div className="rounded-xl bg-gray-50 p-3"><p className="text-[10px] uppercase tracking-wide text-gray-400">Signed in as</p><p className="mt-1 text-sm font-bold">{currentUser}</p><p className="text-xs text-gray-500">Same access role</p></div><button onClick={logout} className="mt-2 flex w-full items-center gap-2 rounded-xl px-3 py-2.5 text-sm font-semibold text-gray-700 hover:bg-gray-50"><LogOut size={17}/>{t.logout}</button></div>}</div></div></div></header>
  <div className="mx-auto flex max-w-7xl"><aside className="sticky top-16 hidden h-[calc(100vh-64px)] w-60 shrink-0 border-r border-gray-200 bg-white px-3 py-5 md:block"><nav className="space-y-1">{nav.map(n=><NavLink key={n.href} {...n} active={path===n.href} language={language}/>)}</nav><div className="mt-7 border-t border-gray-100 pt-5"><p className="px-3 text-[10px] font-bold uppercase tracking-wider text-gray-400">Operations</p>{[["/give-crates",t.giveCrates,Plus],["/collect",t.recordPickup,PackageCheck],["/wholesalers",t.wholesalers,Truck],["/crate-types",t.crateTypes,Boxes],["/whatsapp",t.whatsappPage,MessageCircle]].map(([href,label,Icon]:any)=><NavLink key={href} href={href} label={label} mr={label} icon={Icon} active={path===href} language={language}/>)}</div></aside>
   <main className="min-w-0 flex-1 px-4 pb-28 pt-5 md:px-7 md:pb-8">{page==="dashboard"&&<Dashboard farmers={farmers} collections={collections} t={t} router={router} onGive={()=>setShowGive(true)}/>} {page==="farmers"&&!farmerDetailId&&<FarmersPage farmers={farmers} search={search} setSearch={setSearch} t={t} router={router} onAdd={()=>setShowAddFarmer(true)}/>} {page==="farmers"&&farmerDetailId&&<FarmerDetailPage farmer={farmers.find(f=>f.id===Number(farmerDetailId))} collections={collections.filter(c=>c.farmerId===Number(farmerDetailId))} t={t} router={router}/>} {page==="collections"&&<PickUpPage farmers={farmers} collections={collections} t={t} router={router} onCreate={createCollection}/>} {page==="reports"&&<ReportsPage farmers={farmers} collections={collections} t={t}/>} {page==="settings"&&<SettingsPage users={users} setUsers={setUsers} t={t} onAddUser={()=>setShowUser(true)}/>} {page==="give-crates"&&<GivePage farmers={farmers} t={t} onSave={giveCrates}/>} {page==="collect"&&<CollectPage farmers={farmers} wholesalers={wholesalers} t={t} onCreate={createCollection} router={router}/>} {page==="wholesalers"&&<WholesalersPage t={t}/>} {page==="crate-types"&&<CrateTypesPage t={t}/>} {page==="whatsapp"&&<WhatsAppPage collections={collections} farmers={farmers} t={t}/>}</main>
  </div>
  <nav className="fixed bottom-0 left-0 right-0 z-30 border-t border-gray-200 bg-white/95 px-2 pb-[env(safe-area-inset-bottom)] backdrop-blur md:hidden"><div className="mx-auto flex max-w-xl justify-around">{nav.map(n=><MobileNav key={n.href} {...n} active={path===n.href} language={language}/>)}</div></nav>
  {menu&&<div className="fixed inset-0 z-50 bg-black/30 md:hidden" onClick={()=>setMenu(false)}><aside className="h-full w-[86%] max-w-sm bg-white p-5 shadow-xl" onClick={e=>e.stopPropagation()}><div className="flex items-center justify-between"><div className="flex items-center gap-2"><span className="flex h-9 w-9 items-center justify-center rounded-xl bg-leaf-700 text-white"><Boxes size={19}/></span><b>Shivam Collection</b></div><button onClick={()=>setMenu(false)}><X/></button></div><div className="mt-5 flex gap-2 rounded-xl bg-gray-50 p-1"><button onClick={()=>setLanguage("en")} className={`flex-1 rounded-lg py-2 text-xs font-bold ${language==="en"?"bg-white shadow-sm text-leaf-700":"text-gray-500"}`}>English</button><button onClick={()=>setLanguage("mr")} className={`flex-1 rounded-lg py-2 text-xs font-bold ${language==="mr"?"bg-white shadow-sm text-leaf-700":"text-gray-500"}`}>मराठी</button></div><div className="mt-4 space-y-1">{[...nav.map(n=>[n.href,language==="mr"?n.mr:n.label,n.icon]),["/give-crates",t.giveCrates,Plus],["/collect",t.recordPickup,PackageCheck],["/wholesalers",t.wholesalers,Truck],["/crate-types",t.crateTypes,Boxes],["/whatsapp",t.whatsappPage,MessageCircle]].map(([href,label,Icon]:any)=><Link key={href} href={href} className={`flex items-center gap-3 rounded-xl px-3 py-3 text-sm font-semibold ${path===href?"bg-leaf-50 text-leaf-700":"text-gray-700 hover:bg-gray-50"}`}><Icon size={18}/>{label}</Link>)}</div><button onClick={logout} className="mt-6 flex w-full items-center gap-3 rounded-xl bg-gray-50 px-3 py-3 text-sm font-bold text-gray-700"><LogOut size={18}/>{t.logout}</button></aside></div>}
  {showAddFarmer&&<FarmerModal t={t} close={()=>setShowAddFarmer(false)} onSave={addFarmer}/>} {showGive&&<GiveModal farmers={farmers} t={t} close={()=>setShowGive(false)} onSave={giveCrates}/>} {showUser&&<UserModal users={users} t={t} close={()=>setShowUser(false)} onSave={(u)=>{setUsers(v=>[...v,u]);setShowUser(false)}}/>}
 </div>;
}

function Login({language,setLanguage,users,onLogin}:{language:Language;setLanguage:(x:Language)=>void;users:User[];onLogin:(u:string)=>void}){const t=tx[language];const [u,setU]=useState("");const [p,setP]=useState("");const [show,setShow]=useState(false);const [error,setError]=useState("");return <main className="flex min-h-screen items-center justify-center bg-[#f5f7f4] p-4"><div className="w-full max-w-md"><div className="mb-5 flex justify-end"><div className="flex items-center gap-1 rounded-xl border border-gray-200 bg-white p-1"><Globe2 size={15} className="ml-2 text-gray-400"/><button onClick={()=>setLanguage("en")} className={`rounded-lg px-3 py-1.5 text-xs font-bold ${language==="en"?"bg-leaf-50 text-leaf-700":"text-gray-500"}`}>English</button><button onClick={()=>setLanguage("mr")} className={`rounded-lg px-3 py-1.5 text-xs font-bold ${language==="mr"?"bg-leaf-50 text-leaf-700":"text-gray-500"}`}>मराठी</button></div></div><div className="rounded-3xl border border-gray-200 bg-white p-6 shadow-xl sm:p-8"><div className="flex h-12 w-12 items-center justify-center rounded-2xl bg-leaf-700 text-white"><Boxes/></div><h1 className="mt-5 text-2xl font-bold">Shivam Collection</h1><p className="mt-1 text-sm text-gray-500">{t.signInHint}</p><form onSubmit={e=>{e.preventDefault();const found=users.find(x=>x.username===u&&x.password===p);if(found)onLogin(found.username);else setError(t.invalid)}} className="mt-6 space-y-4"><Field label={t.username}><input autoFocus className="input" value={u} onChange={e=>setU(e.target.value)} /></Field><Field label={t.password}><div className="relative"><input type={show?"text":"password"} className="input pr-11" value={p} onChange={e=>setP(e.target.value)}/><button type="button" onClick={()=>setShow(!show)} className="absolute right-3 top-3 text-gray-400">{show?<EyeOff size={18}/>:<Eye size={18}/>}</button></div></Field>{error&&<p className="rounded-xl bg-red-50 p-3 text-xs font-semibold text-red-700">{error}</p>}<button className="w-full rounded-xl bg-leaf-700 py-3.5 font-bold text-white">{t.signIn}</button></form><p className="mt-4 rounded-xl bg-gray-50 p-3 text-xs text-gray-500">{t.demoCreds}</p><p className="mt-3 flex items-center gap-2 text-xs text-gray-400"><ShieldCheck size={14}/>{t.expires}</p></div></div></main>}

function Dashboard({farmers,collections,t,router,onGive}:{farmers:Farmer[];collections:Collection[];t:any;router:any;onGive:()=>void}){const [scope,setScope]=useState<"overall"|"today">("overall");const now=new Date();const todayLabel=`${now.getDate()} ${now.toLocaleString("en-US",{month:"short"})} ${now.getFullYear()}`;const totalGiven=farmers.reduce((a,f)=>a+f.given,0),totalCollected=farmers.reduce((a,f)=>a+f.collected,0),totalPending=farmers.reduce((a,f)=>a+f.pending,0);const todayCollected=collections.filter(c=>c.date.includes(todayLabel)).reduce((a,c)=>a+c.collected,0);const todayGiven=collections.filter(c=>c.date.includes(todayLabel)).reduce((a,c)=>a+c.given,0);const given=scope==="today"?todayGiven:totalGiven,collected=scope==="today"?todayCollected:totalCollected,pending=Math.max(0,given-collected);const completion=given?Math.round(collected/given*100):0;const sorted=collections.filter(c=>c.sorted).length,unsorted=collections.length-sorted;const top=Object.entries(collections.reduce((a,c)=>({...a,[c.wholesaler]:(a[c.wholesaler]||0)+c.collected}),{} as Record<string,number>)).sort((a,b)=>b[1]-a[1])[0]?.[0]||"—";return <PageHeader title={t.dashboard} subtitle={`${t.welcome}, Shivam`}><div className="flex flex-wrap gap-2"><div className="flex rounded-xl border border-gray-200 bg-white p-1"><button onClick={()=>setScope("overall")} className={`rounded-lg px-4 py-2 text-xs font-bold ${scope==="overall"?"bg-leaf-700 text-white":"text-gray-500"}`}>{t.overall}</button><button onClick={()=>setScope("today")} className={`rounded-lg px-4 py-2 text-xs font-bold ${scope==="today"?"bg-leaf-700 text-white":"text-gray-500"}`}>{t.today}</button></div><button onClick={onGive} className="ml-auto inline-flex items-center gap-2 rounded-xl bg-leaf-700 px-4 py-2.5 text-sm font-bold text-white"><Plus size={17}/>{t.giveCrates}</button><button onClick={()=>router.push("/collections")} className="inline-flex items-center gap-2 rounded-xl border border-gray-200 bg-white px-4 py-2.5 text-sm font-bold"><PackageCheck size={17}/>{t.pickUp}</button></div><div className="mt-5 grid grid-cols-2 gap-3 lg:grid-cols-4"><Metric title={t.given} value={given} sub="crates" icon={ArrowUpFromLine}/><Metric title={t.collected} value={collected} sub="crates" icon={ArrowDownToLine}/><Metric title={t.pending} value={pending} sub="crates" warning icon={Clock3}/><Metric title={t.completion} value={`${completion}%`} sub="of given" icon={Check}/></div><div className="mt-6 grid gap-4 lg:grid-cols-[1.3fr_.7fr]"><Card><div className="flex items-center justify-between"><div><h3 className="font-bold">{t.collectionSnapshot}</h3><p className="mt-1 text-xs text-gray-500">{scope==="today"?t.today:t.overall}</p></div><span className="rounded-full bg-leaf-50 px-3 py-1 text-xs font-bold text-leaf-700">{t.lastUpdated}</span></div><div className="mt-5 grid gap-3 sm:grid-cols-2"><Info label={t.sortedCollections} value={`${sorted}`} green/><Info label={t.unsortedCollections} value={`${unsorted}`}/><Info label={t.topDestination} value={top}/><Info label={t.farmerCoverage} value={`${farmers.filter(f=>f.given>0).length} / ${farmers.length}`}/></div></Card><Card><h3 className="font-bold">{t.pickUpStatus}</h3><div className="mt-5 space-y-4"><Progress label={t.collected} value={collected} total={given}/><Progress label={t.pending} value={pending} total={given}/></div><button onClick={()=>router.push("/collections")} className="mt-5 flex w-full items-center justify-between rounded-xl bg-gray-50 px-4 py-3 text-sm font-bold">{t.pickUp}<ChevronRight size={17}/></button></Card></div><div className="mt-4"><Card><div className="flex items-center justify-between"><div><h3 className="font-bold">{t.pending}</h3><p className="mt-1 text-xs text-gray-500">{farmers.filter(f=>f.pending>0).length} farmers with crates to pick up</p></div><button onClick={()=>router.push("/collections")} className="text-xs font-bold text-leaf-700">View all</button></div><div className="mt-4 grid gap-2 sm:grid-cols-2 lg:grid-cols-3">{farmers.filter(f=>f.pending>0).slice(0,6).map(f=><div key={f.id} className="flex items-center justify-between rounded-xl border border-gray-100 px-3 py-3"><div><b className="text-sm">{f.name}</b><p className="text-xs text-gray-500">{f.village}</p></div><span className="rounded-full bg-amber-50 px-2.5 py-1 text-xs font-bold text-amber-800">{f.pending} {t.pending}</span></div>)}</div></Card></div></PageHeader>}

function FarmersPage({farmers,search,setSearch,t,router,onAdd}:{farmers:Farmer[];search:string;setSearch:(x:string)=>void;t:any;router:any;onAdd:()=>void}){const filtered=farmers.filter(f=>`${f.name} ${f.village} ${f.phone}`.toLowerCase().includes(search.toLowerCase()));return <PageHeader title={t.farmers} subtitle={`${farmers.length} farmers`} action={<button onClick={onAdd} className="inline-flex items-center gap-2 rounded-xl bg-leaf-700 px-4 py-2.5 text-sm font-bold text-white"><Plus size={17}/>{t.addFarmer}</button>}><div className="mb-4 relative"><Search className="absolute left-3 top-3 text-gray-400" size={18}/><input className="input pl-10" placeholder={t.searchFarmers} value={search} onChange={e=>setSearch(e.target.value)}/></div><div className="grid gap-3 md:grid-cols-2 lg:grid-cols-3">{filtered.map(f=><button key={f.id} onClick={()=>router.push(`/farmers/${f.id}`)} className="rounded-2xl border border-gray-200 bg-white p-4 text-left shadow-sm transition hover:-translate-y-0.5 hover:shadow-md"><div className="flex items-center gap-3"><Avatar name={f.name}/><div className="min-w-0 flex-1"><b className="block truncate text-sm">{f.name}</b><p className="mt-0.5 flex items-center gap-1 text-xs text-gray-500"><MapPin size={12}/>{f.village} · {f.phone}</p></div><ChevronRight size={17} className="text-gray-400"/></div><div className="mt-4 grid grid-cols-3 gap-2"><Info label={t.given} value={`${f.given}`} /><Info label={t.collected} value={`${f.collected}`} green/><Info label={t.pending} value={`${f.pending}`} warning/></div></button>)}</div>{filtered.length===0&&<Empty title="No farmers found" text="Try another search."/>}</PageHeader>}

function PickUpPage({farmers,collections,t,router,onCreate}:{farmers:Farmer[];collections:Collection[];t:any;router:any;onCreate:(x:any)=>void}){const [tab,setTab]=useState<"pending"|"picked">("pending");const pending=farmers.filter(f=>f.pending>0);const picked=collections.filter(c=>c.collected>0);return <PageHeader title={t.pickUpTitle} subtitle="Collections to pick up and pickup history"><div className="flex rounded-xl border border-gray-200 bg-white p-1"><button onClick={()=>setTab("pending")} className={`flex-1 rounded-lg px-4 py-2.5 text-sm font-bold ${tab==="pending"?"bg-leaf-700 text-white":"text-gray-500"}`}>{t.pendingTab} <span className="ml-1 rounded-full bg-white/20 px-1.5 py-0.5 text-xs">{pending.length}</span></button><button onClick={()=>setTab("picked")} className={`flex-1 rounded-lg px-4 py-2.5 text-sm font-bold ${tab==="picked"?"bg-leaf-700 text-white":"text-gray-500"}`}>{t.pickedUpTab}</button></div>{tab==="pending"?<div className="mt-4 space-y-3">{pending.map(f=><div key={f.id} className="rounded-2xl border border-gray-200 bg-white p-4"><div className="flex items-center gap-3"><Avatar name={f.name}/><div className="flex-1"><b className="text-sm">{f.name}</b><p className="text-xs text-gray-500">{f.village} · {f.pending} crates pending</p>{f.assignedWholesaler&&<p className="mt-1 text-[11px] font-semibold text-leaf-700">→ {f.assignedWholesaler}</p>}</div><button onClick={()=>router.push(`/collect?farmer=${f.id}`)} className="rounded-xl bg-leaf-700 px-3 py-2 text-xs font-bold text-white">{t.recordPickup}</button></div><div className="mt-3 grid grid-cols-3 gap-2"><Info label={t.given} value={`${f.given}`}/><Info label={t.collected} value={`${f.collected}`} green/><Info label={t.pending} value={`${f.pending}`} warning/></div></div>)}{pending.length===0&&<Empty title={t.noPending} text="All given crates are picked up."/>}</div>:<div className="mt-4 space-y-2">{picked.map(c=><button key={c.id} onClick={()=>router.push(`/collections/${c.id}`)} className="flex w-full items-center gap-3 rounded-2xl border border-gray-200 bg-white p-4 text-left"><Avatar name={c.farmer}/><div className="flex-1"><b className="text-sm">{c.farmer}</b><p className="text-xs text-gray-500">{c.date} · {c.collected} crates · {c.sorted?t.sorted:t.unsorted}</p></div><ChevronRight size={17} className="text-gray-400"/></button>)}</div>}</PageHeader>}

function GivePage({farmers,t,onSave}:{farmers:Farmer[];t:any;onSave:(id:number,qty:number)=>void}){const [id,setId]=useState(farmers[0]?.id||0);const [qty,setQty]=useState("");return <PageHeader title={t.giveCrates} subtitle="Assign empty crates to a farmer"><Card><Field label={t.selectFarmer}><select className="input" value={id} onChange={e=>setId(Number(e.target.value))}>{farmers.map(f=><option key={f.id} value={f.id}>{f.name} · {f.village}</option>)}</select></Field><Field label={t.cratesGiven} className="mt-4"><input type="number" min="1" className="input" value={qty} onChange={e=>setQty(e.target.value)}/></Field><div className="mt-4 rounded-xl bg-blue-50 p-3 text-xs text-blue-800">Destination wholesaler will be selected when this farmer comes for <b>{t.pickUpTitle}</b>. It is not assigned when empty crates are given.</div><button disabled={!Number(qty)} onClick={()=>onSave(id,Number(qty))} className="mt-5 w-full rounded-xl bg-leaf-700 py-3.5 font-bold text-white disabled:opacity-40">{t.save}</button><p className="mt-3 text-xs text-gray-500">After saving, these crates automatically appear under <b>{t.pickUpTitle} → {t.pendingTab}</b>.</p></Card></PageHeader>}

function CollectPage({farmers,wholesalers,t,onCreate,router}:{farmers:Farmer[];wholesalers:Wholesaler[];t:any;onCreate:(x:any)=>void;router:any}){const qs=typeof window!=="undefined"?new URLSearchParams(window.location.search):null;const [farmerId,setFarmerId]=useState(Number(qs?.get("farmer"))||farmers[0]?.id||0);const farmer=farmers.find(f=>f.id===farmerId)||farmers[0];const [collected,setCollected]=useState("");const [sorted,setSorted]=useState(true);const [wholesaler,setWholesaler]=useState(wholesalers[0].name);const [items,setItems]=useState<Record<string,number>>({});const totalSorted=Object.values(items).reduce((a,b)=>a+Number(b||0),0);const total=sorted?totalSorted:Number(collected||0);const remaining=Math.max(0,(farmer?.pending||0)-total);return <PageHeader title={t.recordPickup} subtitle={`${farmer?.name||""} · ${farmer?.pending||0} crates pending`}><Card><Field label={t.selectFarmer}><select className="input" value={farmerId} onChange={e=>setFarmerId(Number(e.target.value))}>{farmers.map(f=><option key={f.id} value={f.id}>{f.name} · {f.pending} pending</option>)}</select></Field><Field label={t.sorting} className="mt-5"><div className="grid grid-cols-2 gap-2"><button onClick={()=>setSorted(true)} className={`rounded-xl border p-3 text-left text-sm font-bold ${sorted?"border-leaf-500 bg-leaf-50 text-leaf-700":"border-gray-200"}`}>{t.yesSorted}</button><button onClick={()=>setSorted(false)} className={`rounded-xl border p-3 text-left text-sm font-bold ${!sorted?"border-amber-400 bg-amber-50 text-amber-800":"border-gray-200"}`}>{t.noSorted}</button></div></Field>{sorted?<div className="mt-5"><div className="flex items-center justify-between"><span className="text-xs font-bold text-gray-600">{t.sortedTypes}</span><span className="rounded-full bg-leaf-50 px-2 py-1 text-xs font-bold text-leaf-700">{totalSorted} total</span></div><div className="mt-2 space-y-2">{crateTypes.map(type=><div key={type} className="flex items-center gap-3 rounded-xl bg-gray-50 p-3"><span className="flex-1 text-sm">{type}</span><input type="number" min="0" className="w-24 rounded-lg border border-gray-200 bg-white px-3 py-2 text-right" value={items[type]||""} onChange={e=>setItems({...items,[type]:Number(e.target.value)})}/></div>)}</div></div>:<Field label={t.collectTotal} className="mt-5"><input type="number" min="0" className="input" value={collected} onChange={e=>setCollected(e.target.value)}/></Field>}<Field label={t.destination} className="mt-5"><select className="input" value={wholesaler} onChange={e=>setWholesaler(e.target.value)}>{wholesalers.map(w=><option key={w.id}>{w.name}</option>)}</select></Field><div className="mt-5 grid grid-cols-3 gap-2"><Info label={t.given} value={`${farmer?.pending||0} pending`} /><Info label={t.collected} value={`${total}`} green/><Info label={t.remaining} value={`${remaining}`} warning/></div><button disabled={!total||!farmer} onClick={()=>{onCreate({farmerId:farmer.id,farmer:farmer.name,date:"27 Sep 2026",given:farmer.pending,collected:total,pending:remaining,sorted,wholesaler,items:sorted?Object.entries(items).filter(([,q])=>q>0).map(([name,qty])=>({name,qty})):[]});router.push("/collections")}} className="mt-5 w-full rounded-xl bg-leaf-700 py-3.5 font-bold text-white disabled:opacity-40">{t.savePickup}</button></Card></PageHeader>}

function ReportsPage({farmers,collections,t}:{farmers:Farmer[];collections:Collection[];t:any}){
 const [query,setQuery]=useState(""); const [page,setPage]=useState(1); const pageSize=10;
 const filtered=farmers.filter(f=>`${f.name} ${f.village} ${f.phone}`.toLowerCase().includes(query.toLowerCase()));
 const pages=Math.max(1,Math.ceil(filtered.length/pageSize)); const rows=filtered.slice((page-1)*pageSize,page*pageSize);
 const totalGiven=farmers.reduce((a,f)=>a+f.given,0),totalCollected=farmers.reduce((a,f)=>a+f.collected,0),pending=farmers.reduce((a,f)=>a+f.pending,0),rate=totalGiven?Math.round(totalCollected/totalGiven*100):0;
 const trend=collections.slice().reverse().map(c=>({day:c.date.split(" ")[0],collected:c.collected,pending:c.pending}));
 const byType=crateTypes.map(type=>({name:type.replace(" Crate",""),qty:collections.reduce((a,c)=>a+(c.items.find(i=>i.name===type)?.qty||0),0)}));
 const byWholesaler=Object.entries(collections.reduce((a,c)=>({...a,[c.wholesaler]:(a[c.wholesaler]||0)+c.collected}),{} as Record<string,number>)).map(([name,qty])=>({name,qty}));
 const wholesalerFor=(farmerId:number)=>{const f=farmers.find(x=>x.id===farmerId); if(f?.assignedWholesaler)return f.assignedWholesaler; const cs=collections.filter(c=>c.farmerId===farmerId); return cs.length?Array.from(new Set(cs.map(c=>c.wholesaler))).join(", "):"—"};
 const exportCsv=()=>{const csv=["Farmer,Village,Wholesaler,Given,Collected,Pending,Completion",...filtered.map(f=>`"${f.name}","${f.village}","${wholesalerFor(f.id).replaceAll('"','""')}",${f.given},${f.collected},${f.pending},${f.given?Math.round(f.collected/f.given*100):0}%`)].join("\n");const blob=new Blob([csv],{type:"text/csv;charset=utf-8"});const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download="farmer-report.csv";a.click();URL.revokeObjectURL(url)};
 return <PageHeader title={t.reports} subtitle="Operational analytics built for scale">
  <div className="grid grid-cols-2 gap-3 lg:grid-cols-4"><Metric title={t.given} value={totalGiven} sub="crates" icon={ArrowUpFromLine}/><Metric title={t.collected} value={totalCollected} sub="crates" icon={ArrowDownToLine}/><Metric title={t.pending} value={pending} sub="crates" warning icon={Clock3}/><Metric title={t.completion} value={`${rate}%`} sub="completion" icon={Check}/></div>
  <div className="mt-6 grid gap-4 lg:grid-cols-2"><Card><h3 className="font-bold">{t.trend}</h3><p className="mt-1 text-xs text-gray-500">Collected and pending over recorded pickups.</p><div className="mt-4 h-64"><ResponsiveContainer width="100%" height="100%"><AreaChart data={trend}><CartesianGrid strokeDasharray="3 3"/><XAxis dataKey="day"/><YAxis/><Tooltip/><Area type="monotone" dataKey="collected" fill="#dceedd" stroke="#32783d"/><Area type="monotone" dataKey="pending" fill="#fff0c7" stroke="#d8a52b"/></AreaChart></ResponsiveContainer></div></Card><Card><h3 className="font-bold">{t.crateTypes}</h3><p className="mt-1 text-xs text-gray-500">Only sorted collections are included.</p><div className="mt-4 h-64"><ResponsiveContainer width="100%" height="100%"><BarChart data={byType}><CartesianGrid strokeDasharray="3 3"/><XAxis dataKey="name" tick={{fontSize:11}}/><YAxis/><Tooltip/><Bar dataKey="qty" fill="#32783d" radius={[6,6,0,0]}/></BarChart></ResponsiveContainer></div></Card></div>
  <div className="mt-4 grid gap-4 lg:grid-cols-[.8fr_1.2fr]"><Card><h3 className="font-bold">{t.wholesalers}</h3><div className="mt-3 space-y-2">{byWholesaler.map(w=><div key={w.name} className="flex items-center justify-between rounded-xl bg-gray-50 px-3 py-3"><span className="text-sm">{w.name}</span><b>{w.qty} crates</b></div>)}</div></Card>
  <Card><div className="flex flex-wrap items-center justify-between gap-3"><div><h3 className="font-bold">{t.farmerReport}</h3><p className="mt-1 text-xs text-gray-500">{t.reportNote}</p></div><div className="flex w-full gap-2 sm:w-auto"><div className="relative flex-1 sm:w-64"><Search className="absolute left-3 top-3 text-gray-400" size={17}/><input className="input pl-9" placeholder={t.searchFarmers} value={query} onChange={e=>{setQuery(e.target.value);setPage(1)}}/></div><button onClick={exportCsv} className="rounded-xl border border-gray-200 bg-white px-3 py-2 text-xs font-bold">Export CSV</button></div></div>
   <div className="mt-4 hidden overflow-x-auto md:block"><table className="w-full text-left text-sm"><thead><tr className="border-b text-xs text-gray-500"><th className="px-2 py-2">Farmer</th><th className="px-2 py-2">Village</th><th className="px-2 py-2">Wholesaler</th><th className="px-2 py-2">Given</th><th className="px-2 py-2">Collected</th><th className="px-2 py-2">Pending</th><th className="px-2 py-2">%</th></tr></thead><tbody>{rows.map(f=><tr key={f.id} className="border-b border-gray-50"><td className="px-2 py-3 font-semibold">{f.name}</td><td className="px-2 py-3 text-gray-500">{f.village}</td><td className="max-w-44 px-2 py-3 text-gray-600">{wholesalerFor(f.id)}</td><td className="px-2 py-3">{f.given}</td><td className="px-2 py-3 text-leaf-700">{f.collected}</td><td className="px-2 py-3 text-amber-700">{f.pending}</td><td className="px-2 py-3">{f.given?Math.round(f.collected/f.given*100):0}%</td></tr>)}</tbody></table></div>
   <div className="mt-4 space-y-2 md:hidden">{rows.map(f=><div key={f.id} className="rounded-2xl border border-gray-100 bg-gray-50 p-3"><div className="flex items-start justify-between gap-3"><div><p className="text-sm font-bold">{f.name}</p><p className="mt-0.5 text-xs text-gray-500">{f.village}</p></div><span className="rounded-full bg-leaf-50 px-2 py-1 text-[10px] font-bold text-leaf-700">{f.given?Math.round(f.collected/f.given*100):0}%</span></div><div className="mt-3 rounded-xl bg-white p-3"><p className="text-[10px] font-bold uppercase tracking-wide text-gray-400">Wholesaler</p><p className="mt-1 text-sm font-semibold">{wholesalerFor(f.id)}</p></div><div className="mt-2 grid grid-cols-3 gap-2"><Info label={t.given} value={`${f.given}`}/><Info label={t.collected} value={`${f.collected}`} green/><Info label={t.pending} value={`${f.pending}`} warning/></div></div>)}{rows.length===0&&<Empty title="No farmers found" text="Try another search."/>}</div>
   <div className="mt-4 flex flex-wrap items-center justify-between gap-2 text-xs text-gray-500"><span>{t.showing} {rows.length} {t.of} {filtered.length}</span><div className="flex gap-2"><button disabled={page<=1} onClick={()=>setPage(page-1)} className="rounded-lg border px-3 py-2 disabled:opacity-40">{t.previous}</button><span className="px-2 py-2">{page}/{pages}</span><button disabled={page>=pages} onClick={()=>setPage(page+1)} className="rounded-lg border px-3 py-2 disabled:opacity-40">{t.next}</button></div></div>
  </Card></div>
 </PageHeader>}

function SettingsPage({users,setUsers,t,onAddUser}:{users:User[];setUsers:(x:User[])=>void;t:any;onAddUser:()=>void}){return <PageHeader title={t.settings} subtitle="Access, language and security"><div className="space-y-4"><Card><div className="flex items-center justify-between"><div><h3 className="font-bold">{t.users}</h3><p className="mt-1 text-xs text-gray-500">{t.userLimit} · same role for all users</p></div><button disabled={users.length>=2} onClick={onAddUser} className="inline-flex items-center gap-2 rounded-xl bg-leaf-700 px-3 py-2 text-xs font-bold text-white disabled:opacity-40"><Plus size={16}/>{t.addUser}</button></div><div className="mt-4 space-y-2">{users.map(u=><div key={u.username} className="flex items-center gap-3 rounded-xl bg-gray-50 p-3"><div className="flex h-9 w-9 items-center justify-center rounded-full bg-white font-bold text-leaf-700">{u.username[0].toUpperCase()}</div><div className="flex-1"><b className="text-sm">{u.username}</b><p className="text-xs text-gray-500">Same access role</p></div><span className="rounded-full bg-leaf-50 px-2 py-1 text-[10px] font-bold text-leaf-700">Active</span></div>)}</div></Card><Card><div className="flex items-center gap-3"><Languages className="text-leaf-700"/><div><h3 className="font-bold">{t.language}</h3><p className="mt-1 text-xs text-gray-500">English / Marathi switch is available in the navbar.</p></div></div></Card><Card><div className="flex items-center gap-3"><ShieldCheck className="text-leaf-700"/><div><h3 className="font-bold">{t.security}</h3><p className="mt-1 text-xs text-gray-500">{t.expires}</p></div></div></Card></div></PageHeader>}

function FarmerModal({t,close,onSave}:{t:any;close:()=>void;onSave:(x:any)=>void}){const [v,setV]=useState<any>({});const [error,setError]=useState("");return <Modal title={t.addFarmer} close={close}><div className="space-y-3"><Field label={t.username.replace("Username","Name")}><input className="input" value={v.name||""} onChange={e=>setV({...v,name:e.target.value})}/></Field><Field label={t.mobile}><input className="input" value={v.phone||""} onChange={e=>setV({...v,phone:e.target.value})}/></Field><Field label={t.whatsapp}><input className="input" value={v.whatsapp||""} onChange={e=>setV({...v,whatsapp:e.target.value})}/></Field><Field label={t.village}><input className="input" value={v.village||""} onChange={e=>setV({...v,village:e.target.value})}/></Field><Field label={t.notes}><textarea className="input min-h-24" value={v.notes||""} onChange={e=>setV({...v,notes:e.target.value})}/></Field>{error&&<p className="text-xs text-red-600">{error}</p>}<button onClick={()=>{if(!v.name||!v.phone||!v.whatsapp||!v.village){setError("Name, mobile, WhatsApp and village are required.");return}onSave(v)}} className="w-full rounded-xl bg-leaf-700 py-3 font-bold text-white">{t.save}</button></div></Modal>}
function GiveModal({farmers,t,close,onSave}:{farmers:Farmer[];t:any;close:()=>void;onSave:(id:number,qty:number,wholesaler:string)=>void}){const [id,setId]=useState(farmers[0]?.id||0);const [qty,setQty]=useState("");const [wholesaler,setWholesaler]=useState(wholesalers[0]?.name||"");return <Modal title={t.giveCrates} close={close}><Field label={t.selectFarmer}><select className="input" value={id} onChange={e=>setId(Number(e.target.value))}>{farmers.map(f=><option key={f.id} value={f.id}>{f.name} · {f.village}</option>)}</select></Field><Field label={t.destination} className="mt-4"><select className="input" value={wholesaler} onChange={e=>setWholesaler(e.target.value)}>{wholesalers.map(w=><option key={w.id} value={w.name}>{w.name} · {w.location}</option>)}</select></Field><Field label={t.cratesGiven} className="mt-4"><input type="number" min="1" className="input" value={qty} onChange={e=>setQty(e.target.value)}/></Field><button disabled={!Number(qty)||!wholesaler} onClick={()=>onSave(id,Number(qty),wholesaler)} className="mt-5 w-full rounded-xl bg-leaf-700 py-3 font-bold text-white disabled:opacity-40">{t.save}</button></Modal>}

function UserModal({users,t,close,onSave}:{users:User[];t:any;close:()=>void;onSave:(x:User)=>void}){const [u,setU]=useState("");const [p,setP]=useState("");const [error,setError]=useState("");return <Modal title={t.createUser} close={close}><p className="mb-4 rounded-xl bg-gray-50 p-3 text-xs text-gray-500">{t.userLimit} · same role as existing user</p><div className="space-y-3"><Field label={t.username}><input className="input" value={u} onChange={e=>setU(e.target.value)}/></Field><Field label={t.password}><input type="password" className="input" value={p} onChange={e=>setP(e.target.value)}/></Field>{error&&<p className="text-xs text-red-600">{error}</p>}<button onClick={()=>{if(users.length>=2){setError(t.limitReached);return}if(!u||p.length<6){setError(t.passwordHint);return}if(users.some(x=>x.username===u)){setError("Username already exists.");return}onSave({username:u,password:p})}} className="w-full rounded-xl bg-leaf-700 py-3 font-bold text-white">{t.save}</button></div></Modal>}

function FarmerDetailPage({farmer,collections,t,router}:{farmer?:Farmer;collections:Collection[];t:any;router:any}){const [open,setOpen]=useState<number|null>(null);if(!farmer)return <Empty title="Farmer not found" text="This farmer does not exist."/>;const given=farmer.given,collected=farmer.collected,pending=farmer.pending,rate=given?Math.round(collected/given*100):0;return <PageHeader title={farmer.name} subtitle={`${farmer.village} · ${farmer.phone}`} action={<button onClick={()=>router.push('/farmers')} className="rounded-xl border border-gray-200 bg-white px-3 py-2 text-xs font-bold">← {t.farmers}</button>}><div className="grid grid-cols-2 gap-3 lg:grid-cols-4"><Metric title={t.given} value={given} sub="crates" icon={ArrowUpFromLine}/><Metric title={t.collected} value={collected} sub="crates" icon={ArrowDownToLine}/><Metric title={t.pending} value={pending} sub="crates" warning icon={Clock3}/><Metric title={t.completion} value={`${rate}%`} sub="completion" icon={Check}/></div><div className="mt-5 grid gap-4 lg:grid-cols-[.75fr_1.25fr]"><Card><h3 className="font-bold">Farmer details</h3><div className="mt-4 space-y-3"><Info label={t.mobile} value={farmer.phone}/><Info label={t.whatsapp} value={farmer.whatsapp}/><Info label={t.village} value={farmer.village}/>{farmer.notes&&<Info label={t.notes} value={farmer.notes}/>}</div><div className="mt-4 grid grid-cols-2 gap-2"><a href={`tel:${farmer.phone}`} className="rounded-xl border border-gray-200 py-2.5 text-center text-xs font-bold">{t.call}</a><a href={`https://wa.me/91${farmer.whatsapp}`} target="_blank" rel="noreferrer" className="rounded-xl bg-[#168b43] py-2.5 text-center text-xs font-bold text-white">{t.message}</a></div></Card><Card><div className="flex items-center justify-between"><div><h3 className="font-bold">{t.activity}</h3><p className="mt-1 text-xs text-gray-500">Tap a pickup to see only its crate details.</p></div><span className="rounded-full bg-gray-50 px-3 py-1 text-xs font-bold">{collections.length}</span></div><div className="mt-4 space-y-2">{collections.length===0&&<Empty title={t.noActivity} text="No pickups recorded for this farmer."/>}{collections.map(c=><div key={c.id} className="rounded-2xl border border-gray-100"><button onClick={()=>setOpen(open===c.id?null:c.id)} className="flex w-full items-center gap-3 p-3 text-left"><div className="flex-1"><p className="text-sm font-bold">{c.date}</p><p className="mt-0.5 text-xs text-gray-500">{c.collected} crates · {c.sorted?t.sorted:t.unsorted} · {c.wholesaler}</p></div>{open===c.id?<ChevronDown className="rotate-180 text-gray-400" size={18}/>:<ChevronRight className="text-gray-400" size={18}/>}</button>{open===c.id&&<div className="border-t border-gray-100 bg-gray-50 p-3"><div className="grid grid-cols-2 gap-2"><Info label="Collected" value={`${c.collected} crates`} green/><Info label="Remaining" value={`${c.pending} crates`} warning/></div>{c.sorted&&c.items.length>0?<div className="mt-3 space-y-1">{c.items.map(i=><div key={i.name} className="flex items-center justify-between rounded-lg bg-white px-3 py-2 text-xs"><span>{i.name.replace(' Crate','')}</span><b>{i.qty} crates</b></div>)}</div>:<p className="mt-3 rounded-lg bg-white p-3 text-xs text-gray-500">Not sorted by farmer; wholesaler will sort.</p>}</div>}</div>)}</div></Card></div></PageHeader>}

function FarmersDetailFallback(){return null}
function WholesalersPage({t}:{t:any}){return <PageHeader title={t.wholesalers} subtitle="Collection destinations"><div className="grid gap-3 md:grid-cols-2 lg:grid-cols-3">{wholesalers.map(w=><Card key={w.id}><div className="flex items-center gap-3"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-leaf-50 text-leaf-700"><Truck size={19}/></div><div><b className="text-sm">{w.name}</b><p className="text-xs text-gray-500">{w.location}</p></div></div><div className="mt-4 flex gap-2"><a href={`tel:${w.phone}`} className="flex-1 rounded-xl border border-gray-200 py-2 text-center text-xs font-bold">{t.call}</a><button className="flex-1 rounded-xl bg-gray-50 py-2 text-xs font-bold">Edit</button></div></Card>)}</div></PageHeader>}
function CrateTypesPage({t}:{t:any}){const [types,setTypes]=useState(crateTypes);const [value,setValue]=useState("");return <PageHeader title={t.crateTypes} subtitle="Predefined types used for sorted collections"><Card><div className="flex gap-2"><input className="input" value={value} onChange={e=>setValue(e.target.value)} placeholder="New crate type"/><button onClick={()=>{if(value.trim()){setTypes([...types,value.trim()]);setValue("")}}} className="rounded-xl bg-leaf-700 px-4 text-sm font-bold text-white">{t.addType}</button></div><div className="mt-4 space-y-2">{types.map((x,i)=><div key={`${x}-${i}`} className="flex items-center justify-between rounded-xl bg-gray-50 px-3 py-3 text-sm"><span>{x}</span><button onClick={()=>setTypes(types.filter((_,j)=>j!==i))}><Trash2 size={16} className="text-gray-400"/></button></div>)}</div></Card></PageHeader>}
function toMarathiDigits(value:string|number){
 const map="०१२३४५६७८९";
 return String(value).replace(/\d/g,d=>map[Number(d)]);
}
function formatMarathiDate(dateValue:string){
 const parsed=new Date(dateValue);
 if(Number.isNaN(parsed.getTime())) return dateValue;
 return `${toMarathiDigits(String(parsed.getDate()).padStart(2,"0"))}/${toMarathiDigits(String(parsed.getMonth()+1).padStart(2,"0"))}/${toMarathiDigits(parsed.getFullYear())}`;
}
function marathiGradeLine(name:string,qty:number){
 const clean=name.replace(/\s*Crate$/i,"").trim();
 return `${clean} -${toMarathiDigits(qty)} कॅरेट`;
}
function buildMarathiWhatsAppMessage(c:Collection){
 const date=formatMarathiDate(c.date);
 const total=toMarathiDigits(c.collected);
 const given=toMarathiDigits(c.given);
 const remaining=toMarathiDigits(c.pending);
 const product=c.items.length>0
   ? c.items[0].name.replace(/\s*Crate$/i,"").trim()
   : "माल";
 if(c.sorted){
   const gradeLines=c.items.length
     ? c.items.map((item,index)=>{
         const clean=item.name.replace(/\s*Crate$/i,"").trim();
         const gradeName=/^\d+\s*नंबर/i.test(clean)?clean:`${index+1} नंबर`;
         return `${gradeName} -${toMarathiDigits(item.qty)} कॅरेट`;
       }).join("\n")
     : "";
   return `ट्रान्सपोर्ट: शिवम
शेतकरी: ${c.farmer}
तारीख: ${date}
📦 एकूण माल: ${total} कॅरेट (${product})

${gradeLines}
तुम्हाला दिलेले कॅरेट ${given}
तुमच्याकडे राहिलेले कॅरेट ${remaining}

हिशोब तपासल्याबद्दल धन्यवाद!`;
 }
 return `ट्रान्सपोर्ट: शिवम
शेतकरी: ${c.farmer}
तारीख: ${date}
📦 एकूण माल: ${total} कॅरेट (${product})
ग्रेडिंग साठी ✓
तुम्हाला दिलेले कॅरेट ${given}
तुमच्याकडे राहिलेले कॅरेट ${remaining}

हिशोब तपासल्याबद्दल धन्यवाद!`;
}
function WhatsAppPage({collections,farmers,t}:{collections:Collection[];farmers:Farmer[];t:any}){
 const c=collections[0];
 if(!c)return <Empty title="No collections" text="Create a pickup first."/>;
 const f=farmers.find(x=>x.id===c.farmerId);
 const message=buildMarathiWhatsAppMessage(c);
 return <PageHeader title={t.whatsappPage} subtitle="Review the Marathi WhatsApp message before sending">
   <Card>
     <div className="rounded-2xl border border-[#d8ead6] bg-[#f0f7ee] p-4">
       <div className="mb-3 flex items-center justify-between gap-3">
         <p className="text-xs font-bold text-leaf-700">WHATSAPP PREVIEW · मराठी</p>
         <span className="rounded-full bg-white px-2.5 py-1 text-[10px] font-bold text-gray-500">{c.sorted?"सॉर्ट केलेला":"ग्रेडिंग साठी"}</span>
       </div>
       <pre className="whitespace-pre-wrap font-sans text-[14px] leading-7 text-gray-800">{message}</pre>
     </div>
     <button onClick={()=>window.open(`https://wa.me/91${f?.whatsapp||""}?text=${encodeURIComponent(message)}`,"_blank")} className="mt-4 flex w-full items-center justify-center gap-2 rounded-xl bg-[#168b43] py-3.5 font-bold text-white">
       <MessageCircle size={18}/> WhatsApp वर पाठवा
     </button>
   </Card>
 </PageHeader>
}
function NavLink({href,label,mr,icon:Icon,active,language}:{href:string;label:string;mr:string;icon:any;active:boolean;language:Language}){return <Link href={href} className={`flex items-center gap-3 rounded-xl px-3 py-2.5 text-sm font-semibold ${active?"bg-leaf-50 text-leaf-700":"text-gray-600 hover:bg-gray-50"}`}><Icon size={18}/>{language==="mr"?mr:label}</Link>}
function MobileNav({href,label,mr,icon:Icon,active,language}:{href:string;label:string;mr:string;icon:any;active:boolean;language:Language}){return <Link href={href} className={`flex min-w-14 flex-col items-center gap-1 px-2 py-2 text-[10px] font-semibold ${active?"text-leaf-700":"text-gray-500"}`}><Icon size={19}/><span>{language==="mr"?mr:label}</span></Link>}
function Metric({title,value,sub,warning,icon:Icon}:{title:string;value:string|number;sub:string;warning?:boolean;icon:any}){return <div className="rounded-2xl border border-gray-200 bg-white p-4 shadow-sm"><div className="flex items-center justify-between"><span className="text-xs font-semibold text-gray-500">{title}</span><span className={`rounded-xl p-2 ${warning?"bg-amber-50 text-amber-700":"bg-leaf-50 text-leaf-700"}`}><Icon size={16}/></span></div><div className="mt-3 text-2xl font-bold">{value}</div><div className="mt-1 text-xs text-gray-400">{sub}</div></div>}
function Progress({label,value,total}:{label:string;value:number;total:number}){const pct=total?Math.min(100,Math.round(value/total*100)):0;return <div><div className="flex justify-between text-xs font-semibold"><span>{label}</span><span>{pct}%</span></div><div className="mt-2 h-2 rounded-full bg-gray-100"><div className="h-2 rounded-full bg-leaf-600" style={{width:`${pct}%`}}/></div></div>}
function Info({label,value,green,warning}:{label:string;value:string;green?:boolean;warning?:boolean}){return <div className={`rounded-xl p-3 ${warning?"bg-amber-50":"bg-gray-50"}`}><p className="text-[10px] text-gray-500">{label}</p><p className={`mt-1 text-sm font-bold ${green?"text-leaf-700":warning?"text-amber-800":""}`}>{value}</p></div>}
function Avatar({name}:{name:string}){return <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-full bg-leaf-50 text-xs font-bold text-leaf-700">{name.split(" ").map(x=>x[0]).join("").slice(0,2)}</div>}
function PageHeader({title,subtitle,action,children}:{title:string;subtitle?:string;action?:React.ReactNode;children:React.ReactNode}){return <div className="mx-auto max-w-6xl"><div className="mb-5 flex items-end justify-between gap-4"><div><h1 className="text-2xl font-bold">{title}</h1>{subtitle&&<p className="mt-1 text-sm text-gray-500">{subtitle}</p>}</div>{action}</div>{children}</div>}
function Card({children}:{children:React.ReactNode}){return <div className="rounded-2xl border border-gray-200 bg-white p-4 shadow-sm sm:p-5">{children}</div>}
function Field({label,children,className=""}:{label:string;children:React.ReactNode;className?:string}){return <label className={`block ${className}`}><span className="mb-1.5 block text-xs font-bold text-gray-600">{label}</span>{children}</label>}
function Modal({title,close,children}:{title:string;close:()=>void;children:React.ReactNode}){return <div className="fixed inset-0 z-50 flex items-end justify-center bg-black/30 p-0 sm:items-center sm:p-4"><div className="max-h-[90vh] w-full overflow-y-auto rounded-t-3xl bg-white p-5 sm:max-w-md sm:rounded-3xl"><div className="mb-5 flex items-center justify-between"><h3 className="font-bold">{title}</h3><button onClick={close}><X/></button></div>{children}</div></div>}
function Empty({title,text}:{title:string;text:string}){return <div className="rounded-2xl border border-dashed border-gray-300 bg-white p-10 text-center"><p className="font-bold">{title}</p><p className="mt-1 text-sm text-gray-500">{text}</p></div>}
